B.Sl=s(["\u0441\u0442\u0443","\u043b\u044e\u0442","\u0441\u0430\u043a","\u043a\u0440\u0430","\u043c\u0430\u0439","\u0447\u044d\u0440","\u043b\u0456\u043f","\u0436\u043d\u0456","\u0432\u0435\u0440","\u043a\u0430\u0441","\u043b\u0456\u0441","\u0441\u043d\u0435"],t.s)
B.er=s(["j","f","m","a","m","j","j","a","s","o","n","d"],t.s)
B.Sm=s(["1-\u056b\u0576 \u0565\u057c\u0561\u0574\u057d\u0575\u0561\u056f","2-\u0580\u0564 \u0565\u057c\u0561\u0574\u057d\u0575\u0561\u056f","3-\u0580\u0564 \u0565\u057c\u0561\u0574\u057d\u0575\u0561\u056f","4-\u0580\u0564 \u0565\u057c\u0561\u0574\u057d\u0575\u0561\u056f"],t.s)
B.bU2=new A.aY("Amnion","Die innere Eihaut, die das Fruchtwasser und das Baby umschlie\xdft. Umgangssprachlich als Fruchtblase bezeichnet.")
B.bTh=new A.aY("Amniozentese","Fruchtwasseruntersuchung. Ab der 15. SSW wird \xfcber eine d\xfcnne Nadel Fruchtwasser entnommen, um das Erbgut des Babys zu untersuchen. Ein kleines Fehlgeburtsrisiko besteht.")
B.bUR=new A.aY("Anti-D-Prophylaxe","Spritze f\xfcr Rhesus-negative Schwangere um die 28. bis 30. SSW und nach der Geburt, die verhindert, dass sich Antik\xf6rper gegen Rhesus-positives Kinderblut bilden.")
B.bTG=new A.aY("Apgar-Wert","Punktesystem (0 bis 10) zur Beurteilung des Neugeborenen nach 1, 5 und 10 Minuten: Atmung, Herzschlag, Hautfarbe, Muskelspannung, Reaktion.")
B.bUA=new A.aY("Austreibungsphase","Die Phase der Geburt vom vollst\xe4ndig ge\xf6ffneten Muttermund bis zur Geburt des Kindes, in der die Presswehen einsetzen.")
B.bTC=new A.aY("Baby-Blues","Kurzzeitiges Stimmungstief am dritten bis f\xfcnften Tag nach der Geburt mit Weinen und Gereiztheit. Vergeht meist nach wenigen Tagen.")
B.bTs=new A.aY("Basaltemperatur","Die K\xf6rpertemperatur morgens im Ruhezustand. Nach dem Eisprung steigt sie um etwa 0,2 bis 0,5 Grad und hilft, den Zyklus zu beobachten.")
B.bU_=new A.aY("Beckenboden","Muskelschicht am unteren Ende des Beckens, die Blase, Darm und Geb\xe4rmutter st\xfctzt. Wird in der Schwangerschaft belastet und l\xe4sst sich trainieren.")
B.bUn=new A.aY("Beckenendlage","Das Baby liegt mit Po oder F\xfc\xdfen nach unten statt mit dem Kopf. Bei etwa 3 bis 5 von 100 Schwangeren zum Termin der Fall.")
B.bTP=new A.aY("Beikost","Alles, was Babys zus\xe4tzlich zu Milch essen. Kinder\xe4rzte empfehlen den Einstieg zwischen dem Beginn des 5. und dem Beginn des 7. Monats, die Stillleitlinie von 2026 eher nach etwa sechs Monaten Stillen.")
B.bUy=new A.aY("Besch\xe4ftigungsverbot","Schutz vor Arbeiten, die dir oder dem Baby schaden k\xf6nnten. Gilt generell oder individuell per \xe4rztlichem Zeugnis, bei vollem Lohn.")
B.bUH=new A.aY("Blasensprung","Das Platzen der Fruchtblase und der Abgang von Fruchtwasser. Kann vor oder w\xe4hrend der Wehen passieren. Danach bitte in die Klinik.")
B.bTV=new A.aY("Bonding","Der Aufbau der Bindung zwischen Eltern und Kind, besonders durch Haut-an-Haut-Kontakt direkt nach der Geburt.")
B.bU5=new A.aY("Braxton-Hicks-Kontraktionen","Unregelm\xe4\xdfige \xdcbungswehen, bei denen sich der Bauch hart anspannt und wieder l\xf6st. Sie sind ab der Schwangerschaftsmitte normal.")
B.bTU=new A.aY("Chorion","\xc4u\xdfere Eihaut, aus der sich zusammen mit Anteilen der Geb\xe4rmutterschleimhaut der Mutterkuchen entwickelt.")
B.bTJ=new A.aY("Chorionzottenbiopsie","Untersuchung, bei der ab der 11. SSW ein St\xfcck Gewebe aus dem Mutterkuchen entnommen wird, um das Erbgut des Babys zu untersuchen.")
B.bTL=new A.aY("CTG","Kardiotokogramm. Zeichnet die Herzt\xf6ne des Babys und die Wehen auf, um zu pr\xfcfen, ob es dem Kind gut geht.")
B.bU0=new A.aY("Dammmassage","Sanftes Dehnen des Damms ab etwa der 34. SSW, das das Risiko f\xfcr Dammrisse bei der Geburt verringern kann.")
B.bU6=new A.aY("Dammriss","Riss des Gewebes zwischen Scheide und After bei der Geburt. Wird nach Schweregraden eingeteilt und meist gen\xe4ht.")
B.bUt=new A.aY("Dammschnitt","Ein Schnitt zwischen Scheide und After, der bei Bedarf die Geburt erleichtert. Wird heute nicht routinem\xe4\xdfig gemacht.")
B.bTi=new A.aY("Doppler-Sonografie","Ultraschall, der Blutfluss in Gef\xe4\xdfen von Nabelschnur, Geb\xe4rmutter oder Baby misst. Wird bei Auff\xe4lligkeiten eingesetzt.")
B.bTT=new A.aY("Doula","Eine Begleiterin, die Frauen vor, w\xe4hrend und nach der Geburt emotional und praktisch unterst\xfctzt, ohne medizinische Aufgaben.")
B.bUj=new A.aY("Dreimonatskoliken","Lange Schreiphasen bei gesunden Babys, meist in den ersten drei bis vier Monaten. Die Ursache ist unklar, sie vergehen von selbst.")
B.bTM=new A.aY("Eileiter","Zwei R\xf6hren zwischen Eierstock und Geb\xe4rmutter. Dort findet die Befruchtung statt.")
B.bTd=new A.aY("Eileiterschwangerschaft","Die befruchtete Eizelle nistet sich im Eileiter statt in der Geb\xe4rmutter ein. Das ist ein Notfall und muss behandelt werden.")
B.bTI=new A.aY("Einnistung","Die befruchtete Eizelle setzt sich etwa sechs bis zehn Tage nach der Befruchtung in der Geb\xe4rmutterschleimhaut fest (Nidation).")
B.bUk=new A.aY("Eisprung","Ein reifes Ei springt aus dem Eierstock, meist etwa 14 Tage vor der n\xe4chsten Periode. Es ist nur 12 bis 24 Stunden befruchtungsf\xe4hig.")
B.bTg=new A.aY("Embryo","Bezeichnung f\xfcr das ungeborene Kind bis zum Ende der 10. Schwangerschaftswoche. Danach spricht man vom F\xf6tus.")
B.bTm=new A.aY("Endometriose","Geb\xe4rmutterschleimhaut-\xe4hnliches Gewebe w\xe4chst au\xdferhalb der Geb\xe4rmutter. Kann Schmerzen und Kinderlosigkeit ausl\xf6sen, ist behandelbar.")
B.bTX=new A.aY("Er\xf6ffnungsphase","Erste Phase der Geburt, in der sich der Muttermund durch Wehen langsam bis auf etwa 10 Zentimeter \xf6ffnet.")
B.bU4=new A.aY("Errechneter Termin (ET)","Der rechnerische Geburtstermin, 280 Tage nach dem ersten Tag der letzten Periode. Nur etwa 4 von 100 Babys kommen genau an diesem Tag.")
B.bU9=new A.aY("F\xf6tus","Bezeichnung f\xfcr das ungeborene Kind ab der 11. Schwangerschaftswoche bis zur Geburt.")
B.bTO=new A.aY("Fontanelle","Weiche Stelle am Kopf des Babys, wo die Sch\xe4delknochen noch nicht zusammengewachsen sind. Die vordere schlie\xdft sich zwischen dem 9. und 18. Monat.")
B.bTp=new A.aY("Fruchtblase","Die mit Fruchtwasser gef\xfcllte H\xfclle, in der das Baby heranw\xe4chst.")
B.bTK=new A.aY("Fruchtwasser","Die Fl\xfcssigkeit in der Fruchtblase. Sie sch\xfctzt das Baby, h\xe4lt die Temperatur und wird st\xe4ndig erneuert.")
B.bUQ=new A.aY("Fundus","Der obere Rand der Geb\xe4rmutter. Sein Stand wird bei Vorsorgeuntersuchungen ertastet und zeigt das Wachstum an.")
B.bUO=new A.aY("Geb\xe4rmutter (Uterus)","Das muskul\xe4re Hohlorgan, in dem das Baby w\xe4chst. Sie ist vor der Schwangerschaft etwa birnengro\xdf.")
B.bUF=new A.aY("Geb\xe4rmutterhals (Zervix)","Der untere, schmale Teil der Geb\xe4rmutter, der in der Schwangerschaft verschlossen ist und sich zur Geburt verk\xfcrzt und \xf6ffnet.")
B.bTy=new A.aY("Geburtsplan","Schriftliche W\xfcnsche zur Geburt. Er hilft im Gespr\xe4ch mit Hebamme und Klinik, garantiert aber keinen bestimmten Ablauf.")
B.bUG=new A.aY("Gelbk\xf6rper","Aus dem Follikel nach dem Eisprung entstehende Hormondr\xfcse, die Progesteron bildet und die fr\xfche Schwangerschaft erh\xe4lt.")
B.bUJ=new A.aY("Gestationsdiabetes","Schwangerschaftsdiabetes. Eine erstmals in der Schwangerschaft auftretende Zuckerverwertungsst\xf6rung, die meist mit Ern\xe4hrung und Bewegung gut zu behandeln ist.")
B.bUe=new A.aY("H\xe4moglobin (Hb)","Der rote Blutfarbstoff, der Sauerstoff transportiert. Der Wert wird mehrfach in der Schwangerschaft kontrolliert, um Blutarmut zu erkennen.")
B.bUL=new A.aY("H\xe4morrhoiden","Erweiterte Blutgef\xe4\xdfe am After, die in der Schwangerschaft h\xe4ufiger auftreten und jucken oder bluten k\xf6nnen.")
B.bUB=new A.aY("HELLP-Syndrom","Eine seltene, ernste Schwangerschaftserkrankung mit Blutver\xe4nderungen und Leberproblemen, verwandt mit der Pr\xe4eklampsie. Warnzeichen sind starke Oberbauchschmerzen.")
B.bTD=new A.aY("Hebamme","Fachfrau (oder Fachmann) f\xfcr Schwangerschaft, Geburt, Wochenbett und Stillzeit. Ihre Betreuung ist Kassenleistung.")
B.bUa=new A.aY("hCG","Humanes Choriongonadotropin, das Schwangerschaftshormon. Es wird nach der Einnistung gebildet und ist im Schwangerschaftstest messbar.")
B.bUC=new A.aY("Hyperemesis gravidarum","Ausgepr\xe4gtes, anhaltendes Schwangerschaftserbrechen mit Gewichtsverlust und Austrocknungsgefahr. Braucht \xe4rztliche Behandlung.")
B.bUK=new A.aY("Kaiserschnitt (Sectio)","Geburt des Kindes durch einen Schnitt in Bauchdecke und Geb\xe4rmutter. Geplant oder als Notfall.")
B.bUo=new A.aY("Kindspech (Mekonium)","Der erste, dunkelgr\xfcne, klebrige Stuhl des Neugeborenen. Geht in den ersten Tagen in normalen Stuhl \xfcber.")
B.bUb=new A.aY("Kolostrum","Die erste Muttermilch in den ersten Tagen, gelblich und reich an Abwehrstoffen.")
B.bTn=new A.aY("Kontraktion","Zusammenziehen der Geb\xe4rmuttermuskulatur. Wird umgangssprachlich als Wehe bezeichnet.")
B.bTt=new A.aY("Lanugo","Feine Flaumbehaarung, die das Baby ab etwa der 14. Woche im Bauch bedeckt.")
B.bTR=new A.aY("Linea nigra","Dunkler Streifen auf dem Bauch vom Nabel abw\xe4rts, hormonell bedingt, verblasst nach der Geburt.")
B.bU1=new A.aY("Lochien","Der Wochenfluss nach der Geburt: Wundfl\xfcssigkeit aus der Geb\xe4rmutter, die vier bis sechs Wochen anh\xe4lt.")
B.bTF=new A.aY("Milcheinschuss","Das Einsetzen der reifen Milchbildung am zweiten bis vierten Tag nach der Geburt, die Brust wird voller und schwerer.")
B.bUI=new A.aY("Milchschorf","Gelbliche Schuppen auf der Kopfhaut von Babys. Harmlos und meist selbst abheilend.")
B.bUm=new A.aY("Montgomery-Dr\xfcsen","Kleine Erhebungen im Warzenhof, die ein pflegendes Sekret bilden und in der Schwangerschaft deutlicher werden.")
B.bUg=new A.aY("Muttermund","Die \xd6ffnung des Geb\xe4rmutterhalses. Sie \xf6ffnet sich unter der Geburt auf etwa 10 Zentimeter.")
B.bTw=new A.aY("Mutterkuchen (Plazenta)","Das Organ, das das Baby mit Sauerstoff und N\xe4hrstoffen versorgt und Hormone bildet. Wird nach der Geburt als Nachgeburt ausgesto\xdfen.")
B.bTZ=new A.aY("Mutterpass","Das Dokument, in dem Vorsorgeuntersuchungen, Werte und Besonderheiten der Schwangerschaft festgehalten werden.")
B.bUP=new A.aY("Mutterschutz","Gesetzlicher Schutz f\xfcr Schwangere und M\xfctter: sechs Wochen vor bis acht Wochen nach der Geburt, dazu K\xfcndigungsschutz und Schutz am Arbeitsplatz.")
B.bUE=new A.aY("Nabelschnur","Die Verbindung zwischen Baby und Mutterkuchen mit einer Vene und zwei Arterien. Rund 50 Zentimeter lang.")
B.bTW=new A.aY("Nachgeburt","Die Geburt von Mutterkuchen und Eih\xe4uten nach der Geburt des Babys, meist innerhalb von 5 bis 30 Minuten.")
B.bUp=new A.aY("Nachwehen","Kontraktionen der Geb\xe4rmutter in den ersten Tagen nach der Geburt, die sie zur\xfcckbilden. Beim Stillen oft st\xe4rker.")
B.bTv=new A.aY("Nackentransparenz","Eine Ultraschallmessung der Fl\xfcssigkeit im Nacken des Babys zwischen der 11. und 14. SSW. Teil des Ersttrimester-Screenings.")
B.bTA=new A.aY("Naegele-Regel","Rechenweg f\xfcr den Geburtstermin: erster Tag der letzten Periode plus 280 Tage, bei abweichender Zyklusl\xe4nge angepasst.")
B.bUh=new A.aY("Neugeborenengelbsucht","Gelbf\xe4rbung von Haut und Augen in den ersten Tagen, weil der K\xf6rper den Blutfarbstoff noch langsam abbaut. Meist harmlos.")
B.bUq=new A.aY("NIPT","Nicht-invasiver Pr\xe4nataltest. Bluttest ab der 10. SSW, der das Erbgut des Babys aus dem Blut der Mutter auf Trisomien untersucht.")
B.bTE=new A.aY("\xd6deme","Wassereinlagerungen im Gewebe, in der Schwangerschaft h\xe4ufig an F\xfc\xdfen und Kn\xf6cheln. Pl\xf6tzlich starke Schwellungen im Gesicht sind abkl\xe4rungsbed\xfcrftig.")
B.bTc=new A.aY("\xd6strogen","Weibliches Geschlechtshormon, das in der Schwangerschaft stark ansteigt und die Geb\xe4rmutter wachsen l\xe4sst.")
B.bTf=new A.aY("Oxytocin","Hormon, das Wehen und die Milchabgabe beim Stillen ausl\xf6st. Wird auch medikament\xf6s zur Wehenf\xf6rderung eingesetzt.")
B.bTS=new A.aY("PCO-Syndrom","Hormonelle St\xf6rung mit seltenen oder ausbleibenden Eispr\xfcngen, unregelm\xe4\xdfigen Zyklen und oft vielen kleinen Zysten in den Eierst\xf6cken.")
B.bU7=new A.aY("Periduralan\xe4sthesie (PDA)","Schmerzbet\xe4ubung \xfcber einen Katheter im R\xfcckenmarkskanal, die die Wehenschmerzen deutlich lindert.")
B.bTB=new A.aY("Plazenta praevia","Der Mutterkuchen liegt vor dem Muttermund. Meist ist ein Kaiserschnitt n\xf6tig, Blutungen im letzten Drittel sind ein Warnzeichen.")
B.bTk=new A.aY("Pr\xe4eklampsie","Erkrankung im letzten Drittel mit hohem Blutdruck und Eiwei\xdf im Urin. Warnzeichen sind Kopfschmerzen, Sehst\xf6rungen und Oberbauchschmerzen.")
B.bUM=new A.aY("Progesteron","Hormon, das die Schwangerschaft erh\xe4lt, die Geb\xe4rmutter ruhigstellt und m\xfcde machen kann.")
B.bTH=new A.aY("Pr\xe4nataldiagnostik","Untersuchungen vor der Geburt, die Hinweise auf Erkrankungen oder Auff\xe4lligkeiten des Babys geben k\xf6nnen. Sie sind freiwillig und sollten beraten begleitet werden.")
B.bUD=new A.aY("Presswehen","Kr\xe4ftige Wehen der Austreibungsphase, bei denen der Drang, mitzuschieben, einsetzt.")
B.bU3=new A.aY("Relaxin","Hormon, das B\xe4nder und Gelenke lockert, damit das Becken bei der Geburt nachgeben kann.")
B.bUN=new A.aY("Rhesusfaktor","Ein Merkmal der roten Blutk\xf6rperchen. Ist die Mutter Rhesus-negativ und das Kind positiv, wird Anti-D-Immunglobulin vorbeugend gegeben.")
B.bUd=new A.aY("Rooming-in","Mutter und Baby sind in der Klinik rund um die Uhr im selben Zimmer, das erleichtert Stillen und Bonding.")
B.bUc=new A.aY("R\xfcckbildung","Die Erholung des K\xf6rpers nach der Geburt, besonders von Geb\xe4rmutter, Beckenboden und Bauchmuskeln. Ein R\xfcckbildungskurs unterst\xfctzt sie.")
B.bUf=new A.aY("Schleimpfropf","Der Sekretpfropf im Geb\xe4rmutterhals, der sich kurz vor der Geburt l\xf6st.")
B.bTQ=new A.aY("Schwangerschaftsstreifen","Dehnungsstreifen der Haut, die durch Gewebedehnung und Veranlagung entstehen und sp\xe4ter hell verblassen.")
B.bTj=new A.aY("Senkwehen","Kontraktionen gegen Ende der Schwangerschaft, bei denen der Kopf des Babys tiefer ins Becken rutscht.")
B.bTr=new A.aY("SIDS","Pl\xf6tzlicher S\xe4uglingstod. Das unerwartete Versterben eines Babys im Schlaf, das sich durch sichere Schlafumgebung, R\xfcckenlage und Rauchfreiheit seltener macht.")
B.bU8=new A.aY("Spina bifida","Offener R\xfccken. Ein Neuralrohrdefekt, dem Fols\xe4ure vorbeugen kann.")
B.bTl=new A.aY("SSW","Schwangerschaftswoche, gez\xe4hlt ab dem ersten Tag der letzten Periode. In der 5. SSW sind vier Wochen vollendet.")
B.bTY=new A.aY("Stillh\xfctchen","D\xfcnne Silikonaufs\xe4tze f\xfcr die Brustwarze, die bei Anlegeproblemen kurzzeitig helfen k\xf6nnen. Nur mit Beratung einsetzen.")
B.bUs=new A.aY("Symphyse","Das Schambeingelenk, das sich in der Schwangerschaft lockert und Schmerzen verursachen kann.")
B.bUr=new A.aY("Toxoplasmose","Infektion mit einem Parasiten, der \xfcber rohes Fleisch oder Katzenkot \xfcbertragen wird. F\xfcr das Baby gef\xe4hrlich, wenn sich die Mutter in der Schwangerschaft erstmals ansteckt.")
B.bTN=new A.aY("Trimester","Ein Schwangerschaftsdrittel: das erste bis zur vollendeten 12. Woche, das zweite bis zur 27., das dritte bis zur Geburt.")
B.bUl=new A.aY("Trisomie 21","Ein zus\xe4tzliches Chromosom 21 (Down-Syndrom). Kann durch Screening und Diagnostik in der Schwangerschaft festgestellt werden. Menschen mit Down-Syndrom leben ein selbstbestimmtes Leben mit individueller Unterst\xfctzung.")
B.bUi=new A.aY("\xdcbertragung","Die Schwangerschaft dauert l\xe4nger als 42+0 Wochen. Ab dem Termin wird engmaschig kontrolliert.")
B.bTo=new A.aY("Ultraschall (Sonografie)","Bildgebende Untersuchung mit Schallwellen, die ohne R\xf6ntgenstrahlen auskommt. In der Schwangerschaft sind drei Basisuntersuchungen vorgesehen.")
B.bTq=new A.aY("Vernix caseosa","Die K\xe4seschmiere, ein wei\xdflicher Schutzfilm auf der Haut des Babys im Fruchtwasser.")
B.bUz=new A.aY("Vitamin K","Wichtig f\xfcr die Blutgerinnung. Neugeborene bekommen es bei den ersten drei U-Untersuchungen, um seltene schwere Blutungen zu verhindern.")
B.bUx=new A.aY("Vorwehen","Unregelm\xe4\xdfige Kontraktionen, die die Geb\xe4rmutter auf die Geburt vorbereiten.")
B.bTe=new A.aY("Wehen","Rhythmische Kontraktionen der Geb\xe4rmutter, die das Baby durch den Geburtskanal schieben.")
B.bTu=new A.aY("Wochenbett","Die sechs bis acht Wochen nach der Geburt, in denen sich der K\xf6rper erholt und sich Mutter und Kind aufeinander einstellen.")
B.bTz=new A.aY("Zeichnungsblutung","Leicht blutiger Schleim kurz vor Geburtsbeginn, weil sich der Muttermund \xf6ffnet.")
B.bUv=new A.aY("Zervixschleim","Der Schleim im Geb\xe4rmutterhals. Rund um den Eisprung ist er klar, dehnbar und durchl\xe4ssig f\xfcr Spermien.")
B.bUw=new A.aY("Zwillinge","Eineiige Zwillinge entstehen aus einer befruchteten Eizelle und sind genetisch gleich. Zweieiige Zwillinge entstehen aus zwei Eizellen.")
B.bUu=new A.aY("Zyklus","Der Zeitraum vom ersten Tag einer Periode bis zum Tag vor der n\xe4chsten, im Durchschnitt 28 Tage, gesund sind 24 bis 38.")
B.bTx=new A.aY("Zygote","Die befruchtete Eizelle, aus der durch Zellteilungen der Embryo entsteht.")
