B.c75=new A.uy("huefte","H\xfcften \xf6ffnen",B.pB,"Sanfte Dehnungen f\xfcr H\xfcfte und Beckenboden, auch zur Vorbereitung auf die Geburt.",B.b9M,"mittel")
B.c7i=new A.e0("Ankommen","Setz dich aufrecht hin, eine Hand liegt auf dem Bauch, eine auf der Brust.",30)
B.c7E=new A.e0("Bauchatmung","Atme so ein, dass sich vor allem die Hand am Bauch hebt, und lang wieder aus.",90)
B.c7D=new A.e0("Rippenatmung","Lege beide H\xe4nde an die Seiten der Rippen und atme in die H\xe4nde hinein.",75)
B.c7o=new A.e0("Lange Ausatmung","Atme vier Sekunden ein und sechs Sekunden aus.",90)
B.c7z=new A.e0("Stille","Atme normal weiter und beobachte, wie es dir geht.",45)
B.bqn=s([B.c7i,B.c7E,B.c7D,B.c7o,B.c7z],t.ka)
B.c77=new A.uy("atem-ruhe","Atem und Ruhe",B.dL,"Kurze Atemyoga-Einheit, die dich beruhigt. Gut vor Terminen oder bei innerer Unruhe.",B.bqn,"leicht")
B.c7h=new A.e0("Schultern und Nacken","Setz dich aufrecht hin und lass den Kopf sanft zu jeder Seite sinken.",60)
B.c79=new A.e0("Katze und Kuh, langsam","Im Vierf\xfc\xdflerstand sehr langsam bewegen, jeder Atemzug eine Bewegung.",75)
B.c7x=new A.e0("Kindshaltung","Knie weit, Oberk\xf6rper sinkt nach vorn, Arme liegen lang. Lass alles los.",90)
B.c7p=new A.e0("Seitenlage mit Kissen","Leg dich auf die linke oder rechte Seite, ein Kissen zwischen den Knien, ein Kissen unter dem Bauch.",120)
B.c7k=new A.e0("Tiefe Entspannung","Sp\xfcr, wie der Atem den K\xf6rper bewegt. Lass Kiefer, Schultern und H\xe4nde weich werden.",120)
B.bjP=s([B.c7h,B.c79,B.c7x,B.c7p,B.c7k],t.ka)
B.c78=new A.uy("abend","Abendyoga zum Einschlafen",B.dL,"Langsame Bewegungen und Dehnungen, die den Tag ausklingen lassen. Alles in der Seitenlage oder im Sitzen.",B.bjP,"leicht")
B.kR=new A.dY([4],t.Ih)
B.c7y=new A.e0("Bauchatmung im Sitz","Setz dich bequem hin und atme tief in den Bauch. Beim Ausatmen sinkt die Bauchdecke.",75)
B.c7e=new A.e0("Beckenboden sanft anspannen","Beim Ausatmen den Beckenboden leicht anheben und beim Einatmen ganz loslassen.",90)
B.c7r=new A.e0("Schulterkreisen","L\xf6se Nacken und Schultern, die beim Tragen und Stillen viel leisten.",60)
B.c7C=new A.e0("Katze und Kuh","Runden und wieder lang machen. Keine tiefe R\xfcckbeuge.",75)
B.c7j=new A.e0("Kindshaltung","Knie weit, Oberk\xf6rper sinkt nach vorn. Entspanne dich.",60)
B.boz=s([B.c7y,B.c7e,B.c7r,B.c7C,B.c7j],t.ka)
B.c73=new A.uy("rueckbildung-sanft","Sanft zur\xfcck in den K\xf6rper",B.kR,"F\xfcr die Zeit nach der Geburt, wenn Hebamme oder \xc4rztin es erlauben: Atem, Beckenboden und Haltung wieder wahrnehmen.",B.boz,"leicht")
